`timescale 1ns/1ps
// apb_gpio: APB4 GPIO with edge/level interrupts.
// Implements interface_spec.md per microarchitecture.md.
module apb_gpio #(
    parameter ADDR_WIDTH = 8,
    parameter N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Pins that exist: bits 0..N-1.
    localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'h1 << N) - 32'h1);

    localparam [3:0] IDX_DATA_OUT = 4'd0;
    localparam [3:0] IDX_DIR      = 4'd1;
    localparam [3:0] IDX_DATA_IN  = 4'd2;
    localparam [3:0] IDX_RISE     = 4'd3;
    localparam [3:0] IDX_FALL     = 4'd4;
    localparam [3:0] IDX_HIGH     = 4'd5;
    localparam [3:0] IDX_LOW      = 4'd6;
    localparam [3:0] IDX_ENABLE   = 4'd7;
    localparam [3:0] IDX_STATUS   = 4'd8;

    // ---------------- APB decode ----------------
    wire       access  = psel & penable;
    wire [3:0] reg_idx = paddr[5:2];
    wire       upper_zero;

    generate
        if (ADDR_WIDTH > 6) begin : g_upper
            assign upper_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
        end else begin : g_noupper
            assign upper_zero = 1'b1;
        end
    endgenerate

    wire mapped    = (paddr[1:0] == 2'b00) & upper_zero & (reg_idx <= IDX_STATUS);
    wire wr_access = access & pwrite & mapped;
    wire rd_access = access & ~pwrite & mapped;

    assign pready  = 1'b1;
    assign pslverr = access & (~mapped | (pwrite & (reg_idx == IDX_DATA_IN)));

    wire [31:0] strb_mask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}};
    wire [31:0] wmask     = strb_mask & PINS;
    wire [31:0] wdata_m   = pwdata & wmask;

    // ---------------- Input widening ----------------
    wire [31:0] gpio_in_w;
    genvar gi;
    generate
        for (gi = 0; gi < 32; gi = gi + 1) begin : g_in
            if (gi < N) begin : g_pin
                assign gpio_in_w[gi] = gpio_in[gi];
            end else begin : g_nopin
                assign gpio_in_w[gi] = 1'b0;
            end
        end
    endgenerate

    // ---------------- Registers ----------------
    reg [31:0] data_out_q;
    reg [31:0] dir_q;
    reg [31:0] in_q;
    reg [31:0] in_prev_q;
    reg [31:0] rise_q;
    reg [31:0] fall_q;
    reg [31:0] high_q;
    reg [31:0] low_q;
    reg [31:0] en_q;
    reg [31:0] status_q;

    wire wr_data_out = wr_access & (reg_idx == IDX_DATA_OUT);
    wire wr_dir      = wr_access & (reg_idx == IDX_DIR);
    wire wr_rise     = wr_access & (reg_idx == IDX_RISE);
    wire wr_fall     = wr_access & (reg_idx == IDX_FALL);
    wire wr_high     = wr_access & (reg_idx == IDX_HIGH);
    wire wr_low      = wr_access & (reg_idx == IDX_LOW);
    wire wr_en       = wr_access & (reg_idx == IDX_ENABLE);
    wire wr_status   = wr_access & (reg_idx == IDX_STATUS);

    wire [31:0] data_out_d = wr_data_out ? ((data_out_q & ~wmask) | wdata_m) : data_out_q;
    wire [31:0] dir_d      = wr_dir      ? ((dir_q      & ~wmask) | wdata_m) : dir_q;
    wire [31:0] rise_d     = wr_rise     ? ((rise_q     & ~wmask) | wdata_m) : rise_q;
    wire [31:0] fall_d     = wr_fall     ? ((fall_q     & ~wmask) | wdata_m) : fall_q;
    wire [31:0] high_d     = wr_high     ? ((high_q     & ~wmask) | wdata_m) : high_q;
    wire [31:0] low_d      = wr_low      ? ((low_q      & ~wmask) | wdata_m) : low_q;
    wire [31:0] en_d       = wr_en       ? ((en_q       & ~wmask) | wdata_m) : en_q;

    // ---------------- Detection and status ----------------
    wire [31:0] rise_ev  = in_q & ~in_prev_q;
    wire [31:0] fall_ev  = ~in_q & in_prev_q;
    wire [31:0] detected = ((rise_ev & rise_q) | (fall_ev & fall_q)
                           | (in_q & high_q) | (~in_q & low_q)) & PINS;
    wire [31:0] clear    = wr_status ? wdata_m : 32'h0;
    wire [31:0] status_d = (status_q & ~clear) | detected;

    always @(posedge pclk) begin
        if (!presetn) begin
            data_out_q <= 32'h0;
            dir_q      <= 32'h0;
            in_q       <= 32'h0;
            in_prev_q  <= 32'h0;
            rise_q     <= 32'h0;
            fall_q     <= 32'h0;
            high_q     <= 32'h0;
            low_q      <= 32'h0;
            en_q       <= 32'h0;
            status_q   <= 32'h0;
        end else begin
            data_out_q <= data_out_d;
            dir_q      <= dir_d;
            in_q       <= gpio_in_w;
            in_prev_q  <= in_q;
            rise_q     <= rise_d;
            fall_q     <= fall_d;
            high_q     <= high_d;
            low_q      <= low_d;
            en_q       <= en_d;
            status_q   <= status_d;
        end
    end

    // ---------------- Outputs ----------------
    assign gpio_out = data_out_q[N-1:0];
    assign gpio_oe  = dir_q[N-1:0];
    assign irq      = |(status_q & en_q);

    reg [31:0] rdata;
    always @* begin
        rdata = 32'h0;
        case (reg_idx)
            IDX_DATA_OUT: rdata = data_out_q;
            IDX_DIR:      rdata = dir_q;
            IDX_DATA_IN:  rdata = in_q;
            IDX_RISE:     rdata = rise_q;
            IDX_FALL:     rdata = fall_q;
            IDX_HIGH:     rdata = high_q;
            IDX_LOW:      rdata = low_q;
            IDX_ENABLE:   rdata = en_q;
            IDX_STATUS:   rdata = status_q;
            default:      rdata = 32'h0;
        endcase
    end

    assign prdata = rd_access ? rdata : 32'h0;

endmodule
=== END FILE ===
