`timescale 1ns/1ps
// Self-checking testbench for apb_gpio at N=8 and N=32 (shared bus).
module apb_gpio_tb;

    reg         clk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [31:0] gin;

    wire [31:0] prdata8, prdata32;
    wire        pready8, pready32, pslverr8, pslverr32;
    wire [7:0]  out8, oe8;
    wire [31:0] out32, oe32;
    wire        irq8, irq32;

    integer passed;
    integer failed;
    reg [8*64-1:0] nonce;
    reg [31:0] rw_m;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
        .pclk(clk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
        .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8),
        .pready(pready8), .pslverr(pslverr8), .gpio_in(gin[7:0]),
        .gpio_out(out8), .gpio_oe(oe8), .irq(irq8));

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
        .pclk(clk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
        .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32),
        .pready(pready32), .pslverr(pslverr32), .gpio_in(gin),
        .gpio_out(out32), .gpio_oe(oe32), .irq(irq32));

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task chk(input ok, input [8*64-1:0] what);
        begin
            if (ok) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("CHECK FAILED: %0s (t=%0t)", what, $time);
            end
        end
    endtask

    task bus_idle_check;
        begin
            chk((prdata8 === 32'h0) && (prdata32 === 32'h0) &&
                (pslverr8 === 1'b0) && (pslverr32 === 1'b0),
                "prdata/pslverr zero outside access");
        end
    endtask

    task idle(input [31:0] n);
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) begin
                @(negedge clk);
                #1;
                bus_idle_check;
            end
        end
    endtask

    task set_pins(input [31:0] v);
        begin
            @(negedge clk);
            gin = v;
        end
    endtask

    task apb_write_p(input [7:0] a, input [31:0] d, input [3:0] s, input exp_err,
                     input chg, input [31:0] pins);
        begin
            @(negedge clk);
            psel = 1'b1; penable = 1'b0; pwrite = 1'b1;
            paddr = a; pwdata = d; pstrb = s;
            if (chg) gin = pins;
            #1;
            chk((prdata8 === 32'h0) && (prdata32 === 32'h0) &&
                (pslverr8 === 1'b0) && (pslverr32 === 1'b0),
                "write setup: prdata/pslverr zero");
            @(negedge clk);
            penable = 1'b1;
            #1;
            chk((pready8 === 1'b1) && (pready32 === 1'b1), "pready high in write access");
            if ((pslverr8 !== exp_err) || (pslverr32 !== exp_err)) begin
                failed = failed + 1;
                $error("write 0x%02h: pslverr %b/%b expected %b (t=%0t)",
                       a, pslverr8, pslverr32, exp_err, $time);
            end else passed = passed + 1;
            chk((prdata8 === 32'h0) && (prdata32 === 32'h0), "prdata zero during write");
            @(posedge clk);
            #1;
            psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0; pwdata = 32'h0;
        end
    endtask

    task apb_write(input [7:0] a, input [31:0] d, input [3:0] s, input exp_err);
        begin
            apb_write_p(a, d, s, exp_err, 1'b0, 32'h0);
        end
    endtask

    task apb_read_check(input [7:0] a, input [31:0] exp, input exp_err);
        begin
            @(negedge clk);
            psel = 1'b1; penable = 1'b0; pwrite = 1'b0;
            paddr = a; pwdata = 32'h0; pstrb = 4'h0;
            #1;
            chk((prdata8 === 32'h0) && (prdata32 === 32'h0) &&
                (pslverr8 === 1'b0) && (pslverr32 === 1'b0),
                "read setup: prdata/pslverr zero");
            @(negedge clk);
            penable = 1'b1;
            #1;
            chk((pready8 === 1'b1) && (pready32 === 1'b1), "pready high in read access");
            if (prdata32 !== exp) begin
                failed = failed + 1;
                $error("read 0x%02h N=32: got %08h expected %08h (t=%0t)", a, prdata32, exp, $time);
            end else passed = passed + 1;
            if (prdata8 !== (exp & 32'h0000_00FF)) begin
                failed = failed + 1;
                $error("read 0x%02h N=8: got %08h expected %08h (t=%0t)",
                       a, prdata8, exp & 32'h0000_00FF, $time);
            end else passed = passed + 1;
            if ((pslverr8 !== exp_err) || (pslverr32 !== exp_err)) begin
                failed = failed + 1;
                $error("read 0x%02h: pslverr %b/%b expected %b (t=%0t)",
                       a, pslverr8, pslverr32, exp_err, $time);
            end else passed = passed + 1;
            @(posedge clk);
            #1;
            psel = 1'b0; penable = 1'b0;
        end
    endtask

    task check_pins(input [31:0] eo, input [31:0] ee);
        begin
            if ((out32 !== eo) || (out8 !== eo[7:0])) begin
                failed = failed + 1;
                $error("gpio_out %08h/%02h expected %08h (t=%0t)", out32, out8, eo, $time);
            end else passed = passed + 1;
            if ((oe32 !== ee) || (oe8 !== ee[7:0])) begin
                failed = failed + 1;
                $error("gpio_oe %08h/%02h expected %08h (t=%0t)", oe32, oe8, ee, $time);
            end else passed = passed + 1;
        end
    endtask

    task check_irq(input e32, input e8);
        begin
            #1;
            chk(irq32 === e32, "irq N=32");
            chk(irq8 === e8, "irq N=8");
        end
    endtask

    task rw_step(input [7:0] a, input [31:0] d, input [3:0] s);
        integer b;
        begin
            apb_write(a, d, s, 1'b0);
            for (b = 0; b < 4; b = b + 1)
                if (s[b]) rw_m[8*b +: 8] = d[8*b +: 8];
            apb_read_check(a, rw_m, 1'b0);
            if (a == 8'h00) check_pins(rw_m, 32'h0);
            if (a == 8'h04) check_pins(32'h0, rw_m);
        end
    endtask

    task rw_test(input [7:0] a);
        begin
            rw_m = 32'h0;
            rw_step(a, 32'hFFFF_FFFF, 4'b1111);
            rw_step(a, 32'h0000_0000, 4'b0101);
            rw_step(a, 32'h1234_5678, 4'b0010);
            rw_step(a, 32'hA5C3_9E81, 4'b1001);
            rw_step(a, 32'h5A5A_5A5A, 4'b0000);
            rw_step(a, 32'h0000_0000, 4'b1111);
        end
    endtask

    task read_all_zero;
        begin
            apb_read_check(8'h00, 32'h0, 1'b0);
            apb_read_check(8'h04, 32'h0, 1'b0);
            apb_read_check(8'h08, 32'h0, 1'b0);
            apb_read_check(8'h0C, 32'h0, 1'b0);
            apb_read_check(8'h10, 32'h0, 1'b0);
            apb_read_check(8'h14, 32'h0, 1'b0);
            apb_read_check(8'h18, 32'h0, 1'b0);
            apb_read_check(8'h1C, 32'h0, 1'b0);
            apb_read_check(8'h20, 32'h0, 1'b0);
        end
    endtask

    task verdict;
        begin
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        end
    endtask

    initial begin
        #2000000;
        failed = failed + 1;
        $error("timeout");
        verdict;
        $finish;
    end

    initial begin
        passed = 0;
        failed = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
        paddr = 8'h0; pwdata = 32'h0; pstrb = 4'h0; gin = 32'h0; rw_m = 32'h0;

        // ---- Reset values ----
        repeat (3) @(posedge clk);
        @(negedge clk);
        presetn = 1'b1;
        check_pins(32'h0, 32'h0);
        check_irq(1'b0, 1'b0);
        read_all_zero;

        // ---- Read/write registers, partial strobes, bits above N ----
        rw_test(8'h00);
        rw_test(8'h04);
        rw_test(8'h0C);
        rw_test(8'h10);
        rw_test(8'h14);
        rw_test(8'h1C);
        check_irq(1'b0, 1'b0);
        rw_test(8'h18);   // low-level enables with pins low set status bits

        // Status holds every bit ever enabled for low level: all ones.
        apb_read_check(8'h20, 32'hFFFF_FFFF, 1'b0);
        // ---- Write-1-to-clear, some bits only ----
        apb_write(8'h20, 32'h0000_00F0, 4'b0001, 1'b0);
        apb_read_check(8'h20, 32'hFFFF_FF0F, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b0110, 1'b0);
        apb_read_check(8'h20, 32'hFF00_000F, 1'b0);
        apb_write(8'h20, 32'h0000_0000, 4'b1111, 1'b0);
        apb_read_check(8'h20, 32'hFF00_000F, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        apb_read_check(8'h20, 32'h0, 1'b0);

        // ---- DATA_IN, read only ----
        set_pins(32'hDEAD_BEEF);
        apb_read_check(8'h08, 32'hDEAD_BEEF, 1'b0);
        apb_write(8'h08, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_read_check(8'h08, 32'hDEAD_BEEF, 1'b0);
        apb_read_check(8'h00, 32'h0, 1'b0);
        set_pins(32'h0);
        idle(2);
        apb_read_check(8'h08, 32'h0, 1'b0);

        // ---- Unmapped addresses ----
        apb_read_check(8'h01, 32'h0, 1'b1);
        apb_read_check(8'h02, 32'h0, 1'b1);
        apb_read_check(8'h03, 32'h0, 1'b1);
        apb_read_check(8'h05, 32'h0, 1'b1);
        apb_read_check(8'h21, 32'h0, 1'b1);
        apb_read_check(8'h24, 32'h0, 1'b1);
        apb_read_check(8'h28, 32'h0, 1'b1);
        apb_read_check(8'h3C, 32'h0, 1'b1);
        apb_read_check(8'h40, 32'h0, 1'b1);
        apb_read_check(8'h80, 32'h0, 1'b1);
        apb_read_check(8'hFC, 32'h0, 1'b1);
        apb_write(8'h01, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_write(8'h02, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_write(8'h03, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_write(8'h24, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_write(8'h40, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_write(8'h41, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_write(8'h44, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_write(8'h5C, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_write(8'h80, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        apb_write(8'hFC, 32'hFFFF_FFFF, 4'b1111, 1'b1);
        read_all_zero;
        check_pins(32'h0, 32'h0);
        check_irq(1'b0, 1'b0);

        // ---- Rising edge: fires once ----
        apb_write(8'h0C, 32'h0001_0003, 4'b1111, 1'b0);
        set_pins(32'h0001_0001);
        idle(2);
        apb_read_check(8'h20, 32'h0001_0001, 1'b0);
        idle(3);
        apb_read_check(8'h20, 32'h0001_0001, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        idle(3);
        apb_read_check(8'h20, 32'h0, 1'b0);
        // One-cycle pulse on pin 1
        set_pins(32'h0001_0003);
        set_pins(32'h0001_0001);
        idle(2);
        apb_read_check(8'h20, 32'h0000_0002, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        idle(2);
        apb_read_check(8'h20, 32'h0, 1'b0);
        apb_write(8'h0C, 32'h0, 4'b1111, 1'b0);

        // ---- Falling edge ----
        apb_write(8'h10, 32'h0001_0001, 4'b1111, 1'b0);
        set_pins(32'h0);
        idle(2);
        apb_read_check(8'h20, 32'h0001_0001, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        idle(3);
        apb_read_check(8'h20, 32'h0, 1'b0);
        apb_write(8'h10, 32'h0, 4'b1111, 1'b0);

        // ---- High level: sets again after a clear ----
        apb_write(8'h14, 32'h8000_0080, 4'b1111, 1'b0);
        idle(2);
        apb_read_check(8'h20, 32'h0, 1'b0);
        set_pins(32'h8000_0080);
        idle(2);
        apb_read_check(8'h20, 32'h8000_0080, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        idle(1);
        apb_read_check(8'h20, 32'h8000_0080, 1'b0);
        set_pins(32'h0);
        idle(2);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        idle(2);
        apb_read_check(8'h20, 32'h0, 1'b0);
        apb_write(8'h14, 32'h0, 4'b1111, 1'b0);

        // ---- Low level ----
        apb_write(8'h18, 32'h0000_0101, 4'b1111, 1'b0);
        idle(2);
        apb_read_check(8'h20, 32'h0000_0101, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        idle(1);
        apb_read_check(8'h20, 32'h0000_0101, 1'b0);
        set_pins(32'h0000_0001);
        idle(2);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        idle(1);
        apb_read_check(8'h20, 32'h0000_0100, 1'b0);
        apb_write(8'h18, 32'h0, 4'b1111, 1'b0);
        idle(2);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        idle(2);
        apb_read_check(8'h20, 32'h0, 1'b0);
        set_pins(32'h0);
        idle(2);

        // ---- A detection beats a clear on the same edge ----
        apb_write(8'h0C, 32'h0000_000C, 4'b1111, 1'b0);
        set_pins(32'h0000_000C);
        idle(2);
        apb_read_check(8'h20, 32'h0000_000C, 1'b0);
        set_pins(32'h0);
        idle(2);
        apb_read_check(8'h20, 32'h0000_000C, 1'b0);
        apb_write_p(8'h20, 32'h0000_000C, 4'b1111, 1'b0, 1'b1, 32'h0000_0004);
        idle(2);
        apb_read_check(8'h20, 32'h0000_0004, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        idle(2);
        apb_read_check(8'h20, 32'h0, 1'b0);
        apb_write(8'h0C, 32'h0, 4'b1111, 1'b0);
        set_pins(32'h0);
        idle(2);
        apb_read_check(8'h20, 32'h0, 1'b0);

        // ---- Interrupt mask ----
        apb_write(8'h14, 32'h0000_0202, 4'b1111, 1'b0);
        set_pins(32'h0000_0202);
        idle(2);
        set_pins(32'h0);
        idle(2);
        apb_write(8'h14, 32'h0, 4'b1111, 1'b0);
        apb_read_check(8'h20, 32'h0000_0202, 1'b0);
        check_irq(1'b0, 1'b0);
        apb_write(8'h1C, 32'h0000_0200, 4'b1111, 1'b0);
        check_irq(1'b1, 1'b0);
        apb_write(8'h1C, 32'h0000_0002, 4'b1111, 1'b0);
        check_irq(1'b1, 1'b1);
        apb_write(8'h20, 32'h0000_0002, 4'b1111, 1'b0);
        check_irq(1'b0, 1'b0);
        apb_read_check(8'h20, 32'h0000_0200, 1'b0);
        apb_write(8'h1C, 32'h0000_0202, 4'b1111, 1'b0);
        check_irq(1'b1, 1'b0);
        apb_write(8'h20, 32'h0000_0200, 4'b1111, 1'b0);
        check_irq(1'b0, 1'b0);
        apb_read_check(8'h20, 32'h0, 1'b0);
        apb_read_check(8'h1C, 32'h0000_0202, 1'b0);

        // ---- Reset again with state set ----
        apb_write(8'h00, 32'hA5A5_A5A5, 4'b1111, 1'b0);
        apb_write(8'h04, 32'h0F0F_0F0F, 4'b1111, 1'b0);
        check_pins(32'hA5A5_A5A5, 32'h0F0F_0F0F);
        apb_write(8'h14, 32'h0000_0001, 4'b1111, 1'b0);
        apb_write(8'h1C, 32'h0000_0001, 4'b1111, 1'b0);
        set_pins(32'h0000_0001);
        idle(3);
        check_irq(1'b1, 1'b1);
        @(negedge clk);
        presetn = 1'b0;
        gin = 32'h0;
        repeat (2) @(posedge clk);
        check_irq(1'b0, 1'b0);
        check_pins(32'h0, 32'h0);
        @(negedge clk);
        presetn = 1'b1;
        check_pins(32'h0, 32'h0);
        check_irq(1'b0, 1'b0);
        read_all_zero;

        idle(2);
        verdict;
        $finish;
    end

